const lookupBarcode = `-- name: LookupBarcode :one
SELECT b.barcode, v.id AS variant_id, v.sku, v.name AS variant_name, p.id AS product_id, p.name AS product_name, p.uom_id, p.status AS product_status, v.status AS variant_status
FROM barcodes b
JOIN product_variants v ON v.id = b.variant_id
JOIN products p ON p.id = v.product_id
WHERE b.company_id = $1 AND b.barcode = $2
`

type LookupBarcodeParams struct {
	CompanyID uuid.UUID `json:"company_id"`
	Barcode   string    `json:"barcode"`
}

type LookupBarcodeRow struct {
	Barcode       string    `json:"barcode"`
	VariantID     uuid.UUID `json:"variant_id"`
	Sku           string    `json:"sku"`
	VariantName   string    `json:"variant_name"`
	ProductID     uuid.UUID `json:"product_id"`
	ProductName   string    `json:"product_name"`
	UomID         uuid.UUID `json:"uom_id"`
	ProductStatus string    `json:"product_status"`
	VariantStatus string    `json:"variant_status"`
}

func (q *Queries) LookupBarcode(ctx context.Context, arg LookupBarcodeParams) (LookupBarcodeRow, error) {
	row := q.db.QueryRow(ctx, lookupBarcode, arg.CompanyID, arg.Barcode)
	var i LookupBarcodeRow
	err := row.Scan(
		&i.Barcode,
		&i.VariantID,
		&i.Sku,
		&i.VariantName,
		&i.ProductID,
		&i.ProductName,
		&i.UomID,
		&i.ProductStatus,
		&i.VariantStatus,
	)
	return i, err
}

